) AS seed (league_name, facility_name, home_name, away_name, start_time, end_time, game_type, playoff_round, game_status)
JOIN League l ON l.league_name = seed.league_name
JOIN Facility f ON f.facility_name = seed.facility_name
LEFT JOIN Team ht ON ht.league_id = l.league_id AND ht.team_name = seed.home_name
LEFT JOIN Team away_t ON away_t.league_id = l.league_id AND away_t.team_name = seed.away_name;

-- Semifinal winners advance to each league's championship game.
-- Finals have intentionally unknown participating teams until the semis finish.
UPDATE Game AS semi
SET next_game_id = champ.game_id
FROM Game AS champ
WHERE semi.league_id = champ.league_id
  AND semi.game_type = 'playoff'
  AND semi.playoff_round = 1
  AND champ.game_type = 'playoff'
  AND champ.playoff_round = 2;

