-- Verify row counts after seeding.
SELECT 'league' AS table_name, COUNT(*) AS row_count FROM League
UNION ALL SELECT 'users', COUNT(*) FROM Users
UNION ALL SELECT 'team', COUNT(*) FROM Team
UNION ALL SELECT 'rostermembership', COUNT(*) FROM RosterMembership
UNION ALL SELECT 'facility', COUNT(*) FROM Facility
UNION ALL SELECT 'game', COUNT(*) FROM Game
UNION ALL SELECT 'scorereport', COUNT(*) FROM ScoreReport
UNION ALL SELECT 'officiatingassignment', COUNT(*) FROM OfficiatingAssignment
UNION ALL SELECT 'incidentreport', COUNT(*) FROM IncidentReport
ORDER BY table_name;
